/* Kind pages (travel-guides/, books/, immigration/, food/, checklists/, ...).
   Each page is a static shell generated by scripts/build-pages.mjs with <meta name="kind"> naming the category.
   This script fills it from the same catalog the home page uses (guides.json, or the Worker when connected),
   so the pages stay current without a rebuild. Cart, saved currency, and categories are shared with site.js
   through the same localStorage keys and the same catalog fields. */
(() => {
  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
  const meta = (name) => ($(`meta[name="${name}"]`) || {}).content || '';
  const KIND = meta('kind');
  const CART_KEY = 'marufi-cart';
  const CURRENCY_KEY = 'marufi-currency';
  const TONES = ['clay', 'pine', 'ink', 'gold'];
  const DEFAULT_CATEGORIES = [
    { key: 'Guide', slug: 'travel-guides', name: 'Travel guides', single: 'Travel guide', format: 'Digital guide', blurb: 'One place, read in one sitting: where to stay, what to skip, and how to move around.' },
    { key: 'Book', slug: 'books', name: 'Books', single: 'Book', format: 'Digital book', blurb: 'Longer reads on a country or a region, for the flight over or the year after.' },
    { key: 'Immigration', slug: 'immigration', name: 'Immigration and settling in', single: 'Immigration help', format: 'Digital help guide', blurb: 'Permits, paperwork, housing, banking, and the first weeks, in the order you will meet them.' },
    { key: 'Food', slug: 'food', name: 'Restaurant and food lists', single: 'Restaurant list', format: 'Digital list', blurb: 'Short, curated lists of where to eat, what to order, and when to go.' },
    { key: 'Checklist', slug: 'checklists', name: 'Checklists and templates', single: 'Checklist', format: 'Digital checklist', blurb: 'Packing lists, moving timelines, budget sheets, and the templates that save a week.' },
    { key: 'Bundle', slug: 'bundles', name: 'Bundles', single: 'Bundle', format: '', blurb: 'Several titles for one place, priced together.' }
  ];
  const store = { name: 'Marufi Digital', currency: 'CAD', currencies: [], endpoint: '', categories: [] };
  let catalog = [];
  let cart = [];
  let displayCurrency = '';

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }
  const isHttps = (v) => typeof v === 'string' && /^https:\/\//i.test(v);
  const isSafeAsset = (v) => typeof v === 'string' && v.trim() && ((/^(assets|covers|samples)\//.test(v) && !v.includes('..')) || isHttps(v));
  const slugify = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  const assetUrl = (v) => (isHttps(v) ? v : `../${v}`);
  function moneyMap(value) {
    const out = {};
    if (value && typeof value === 'object') for (const [code, amount] of Object.entries(value)) if (/^[A-Z]{3}$/.test(code) && Number.isFinite(Number(amount))) out[code] = Number(amount);
    return out;
  }
  function formatMoney(amount, currency) {
    try { return new Intl.NumberFormat(undefined, { style: 'currency', currency, minimumFractionDigits: Number.isInteger(amount) ? 0 : 2 }).format(amount); }
    catch { return `${currency} ${amount}`; }
  }
  function readStore(key) { try { const v = JSON.parse(localStorage.getItem(key) || '[]'); return Array.isArray(v) ? v : []; } catch { return []; } }
  function writeStore(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* private mode */ } }

  function setCategories(list) {
    const custom = Array.isArray(list) ? list.filter((c) => c && typeof c.key === 'string' && typeof c.name === 'string') : [];
    const merged = DEFAULT_CATEGORIES.map((d) => ({ ...d, ...(custom.find((c) => c.key.toLowerCase() === d.key.toLowerCase()) || {}), key: d.key, slug: d.slug }));
    for (const c of custom) if (!merged.some((m) => m.key.toLowerCase() === c.key.toLowerCase())) merged.push({ single: c.name, format: 'Digital download', blurb: '', slug: slugify(c.name), ...c });
    store.categories = merged.map((c) => ({ ...c, hidden: c.hidden === true }));
  }
  const categoryOf = (type) => store.categories.find((c) => c.key.toLowerCase() === String(type || '').toLowerCase()) || store.categories[0];

  function normalise(g, index) {
    return {
      id: String(g.id || g.priceId || g.paymentLink || `item-${index}`),
      type: categoryOf(g.type).key,
      country: typeof g.country === 'string' ? g.country.trim() : '',
      state: typeof g.state === 'string' ? g.state.trim() : '',
      title: String(g.title).trim(),
      description: String(g.description).trim(),
      highlights: Array.isArray(g.highlights) ? g.highlights.filter((h) => typeof h === 'string' && h.trim()).slice(0, 3) : [],
      tags: Array.isArray(g.tags) ? g.tags.filter((t) => typeof t === 'string') : [],
      price: Number(g.price),
      prices: moneyMap(g.prices),
      salePrice: Number.isFinite(Number(g.salePrice)) ? Number(g.salePrice) : NaN,
      salePrices: moneyMap(g.salePrices),
      saleEnds: typeof g.saleEnds === 'string' && !Number.isNaN(Date.parse(g.saleEnds)) ? Date.parse(g.saleEnds) : 0,
      variants: Array.isArray(g.variants) ? g.variants.length : 0,
      paymentLink: isHttps(g.paymentLink) ? g.paymentLink : '',
      cover: isSafeAsset(g.cover) ? g.cover : '',
      coverAlt: typeof g.coverAlt === 'string' ? g.coverAlt : '',
      badge: typeof g.badge === 'string' ? g.badge.trim().slice(0, 24) : '',
      featured: g.featured === true,
      preorder: g.preorder === true || (typeof g.releaseDate === 'string' && Date.parse(g.releaseDate) > Date.now())
    };
  }
  const saleActive = (g) => Number.isFinite(g.salePrice) && g.salePrice < g.price && (!g.saleEnds || g.saleEnds > Date.now());
  function priceInfo(g) {
    const cur = displayCurrency || store.currency;
    let amount = Number.isFinite(g.prices[cur]) ? g.prices[cur] : null;
    let currency = cur;
    if (amount === null) { amount = g.price; currency = store.currency; }
    if (saleActive(g)) {
      const sale = Number.isFinite(g.salePrices[currency]) ? g.salePrices[currency] : currency === store.currency ? g.salePrice : Math.round(amount * (g.salePrice / g.price) * 100) / 100;
      return { amount: sale, was: amount, currency };
    }
    return { amount, was: null, currency };
  }
  function priceNode(g) {
    const info = priceInfo(g);
    const node = el('span', 'card-price');
    if (info.was !== null) node.append(el('s', null, formatMoney(info.was, info.currency)), ' ', el('span', 'price-now', formatMoney(info.amount, info.currency)));
    else node.textContent = formatMoney(info.amount, info.currency);
    return node;
  }
  function saleLabel(g) {
    if (!saleActive(g)) return '';
    if (!g.saleEnds) return 'Sale';
    const days = Math.max(0, Math.ceil((g.saleEnds - Date.now()) / 86400000));
    return days <= 1 ? 'Sale · ends today' : `Sale · ${days} days left`;
  }

  /* ---------- Cart (shared with the home page) ---------- */
  function renderCartCount() {
    const count = $('#kind-cart-count');
    if (!count) return;
    count.textContent = String(cart.length);
    count.hidden = cart.length === 0;
  }
  function toggleCart(g, button) {
    if (cart.includes(g.id)) cart = cart.filter((k) => k !== g.id);
    else cart = [...cart, g.id];
    writeStore(CART_KEY, cart);
    renderCartCount();
    paintCartButton(g, button);
    toast(cart.includes(g.id) ? `Added “${g.title}” to your cart` : `Removed “${g.title}” from your cart`);
  }
  function paintCartButton(g, button) {
    const inCart = cart.includes(g.id);
    button.classList.toggle('is-added', inCart);
    button.textContent = inCart ? 'In your cart ✓' : 'Add to cart';
  }
  let toastTimer = 0;
  function toast(text) {
    let node = $('#kind-toast');
    if (!node) { node = el('div', 'toast'); node.id = 'kind-toast'; node.setAttribute('role', 'status'); document.body.append(node); }
    node.textContent = text;
    node.classList.add('is-visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => node.classList.remove('is-visible'), 2600);
  }

  /* ---------- Cards ---------- */
  function coverFor(g) {
    if (g.cover) {
      const img = document.createElement('img');
      img.src = assetUrl(g.cover);
      img.alt = g.coverAlt || `Cover of ${g.title}`;
      img.loading = 'lazy';
      img.decoding = 'async';
      return img;
    }
    const art = el('div', 'cover-art');
    art.dataset.tone = TONES[Math.max(0, catalog.indexOf(g)) % TONES.length];
    art.append(el('span', null, g.country || categoryOf(g.type).single), el('strong', null, g.state || g.title));
    return art;
  }
  function buildCard(g, index) {
    const card = el('article', 'guide-card');
    card.style.setProperty('--i', String(index % 9));
    card.setAttribute('aria-label', g.title);
    const detail = `../?open=${encodeURIComponent(g.id)}`;
    const cover = el('a', 'card-cover');
    cover.href = detail;
    cover.append(coverFor(g));
    const badge = saleLabel(g) || (g.preorder ? 'Pre-order' : g.badge);
    if (badge) cover.append(el('span', `card-badge${saleActive(g) ? ' is-sale' : g.preorder ? ' is-preorder' : ''}`, badge));
    cover.append(el('span', 'card-peek', 'Details'));
    const body = el('div', 'card-body');
    const metaRow = el('div', 'card-meta');
    const place = [g.country, g.state].filter(Boolean).join(' / ');
    metaRow.append(el('span', 'card-kicker', place ? `${categoryOf(g.type).single} · ${place}` : categoryOf(g.type).single), priceNode(g));
    const title = el('h3');
    const link = el('a', 'title-button', g.title);
    link.href = detail;
    title.append(link);
    body.append(metaRow, title, el('p', null, g.description));
    if (g.highlights.length) { const ul = el('ul', 'quick-highlights'); for (const h of g.highlights) ul.append(el('li', null, h)); body.append(ul); }
    const actions = el('div', 'card-actions');
    const buy = el('a', 'button button-sm');
    buy.href = g.paymentLink && !g.variants ? g.paymentLink : detail;
    buy.append(document.createTextNode(g.preorder ? 'Pre-order ' : 'Buy now '));
    const arrow = el('span', null, '→'); arrow.setAttribute('aria-hidden', 'true'); buy.append(arrow);
    const add = el('button', 'button-ghost'); add.type = 'button';
    paintCartButton(g, add);
    add.addEventListener('click', () => toggleCart(g, add));
    actions.append(buy, add);
    body.append(actions);
    card.append(cover, body);
    return card;
  }

  /* ---------- Page ---------- */
  function render(cat, resources) {
    const all = catalog.filter((g) => g.type === cat.key);
    const countries = [...new Set(all.map((g) => g.country).filter(Boolean))].sort((a, b) => a.localeCompare(b));
    const states = new Set(all.map((g) => `${g.country}/${g.state}`).filter((v) => !v.endsWith('/')));
    const stats = $('#kind-stats');
    if (stats) {
      stats.replaceChildren();
      const row = (label, value) => { const li = el('li'); li.append(el('span', null, label), el('strong', null, value)); return li; };
      stats.append(row('Titles', all.length ? String(all.length) : 'Coming soon'), row('Countries', countries.length ? String(countries.length) : '—'), row('States and provinces', states.size ? String(states.size) : '—'));
    }
    const select = $('#kind-country');
    if (select) { select.replaceChildren(el('option', null, 'All countries')); select.firstElementChild.value = ''; for (const c of countries) { const o = el('option', null, c); o.value = c; select.append(o); } }
    const search = $('#kind-search');
    const grid = $('#kind-grid');
    const count = $('#kind-count');
    const empty = $('#kind-empty');
    const toolbar = $('#kind-toolbar');
    if (toolbar) toolbar.hidden = all.length === 0;
    const update = () => {
      const q = search ? search.value.trim().toLocaleLowerCase() : '';
      const country = select ? select.value : '';
      const shown = all.filter((g) => (!country || g.country === country) && (!q || `${g.title} ${g.country} ${g.state} ${g.description} ${g.tags.join(' ')}`.toLocaleLowerCase().includes(q)));
      grid.replaceChildren(...shown.map(buildCard));
      if (count) count.textContent = all.length ? `${shown.length} of ${all.length} ${all.length === 1 ? 'title' : 'titles'}` : '';
      if (empty) {
        empty.hidden = shown.length > 0;
        const h = empty.querySelector('h3'); const p = empty.querySelector('p');
        if (!all.length) { h.textContent = `The first ${cat.name.toLowerCase()} are being written.`; p.textContent = 'Tell us the place you need and we will write to you when it is ready.'; }
        else { h.textContent = 'Nothing matches your search.'; p.textContent = 'Try a different place or a different word.'; }
      }
    };
    if (search) search.addEventListener('input', update);
    if (select) select.addEventListener('change', update);
    update();

    // Free help filed under this kind
    const help = $('#kind-help');
    const helpList = $('#kind-help-list');
    if (help && helpList) {
      const mine = resources.filter((r) => r && typeof r.title === 'string' && r.url && String(r.category || '').toLowerCase() === cat.name.toLowerCase());
      help.hidden = mine.length === 0;
      helpList.replaceChildren(...mine.map((r) => {
        const a = el('a', 'help-card');
        a.href = isHttps(r.url) ? r.url : `../${r.url}`;
        if (isHttps(r.url)) { a.target = '_blank'; a.rel = 'noopener'; }
        const kicker = el('span', 'card-kicker');
        kicker.append(el('span', null, r.place || 'Free'), el('span', null, r.kind || 'Read'));
        a.append(kicker, el('h3', null, r.title), el('p', null, r.summary || ''), el('span', 'text-link', `${r.kind === 'Download' ? 'Download' : r.kind === 'Link' ? 'Open' : 'Read'} →`));
        return a;
      }));
    }

    // The other kinds
    const others = $('#kind-others');
    if (others) {
      others.replaceChildren(...store.categories.filter((c) => c.key !== cat.key && !c.hidden && (c.key !== 'Bundle' || catalog.some((g) => g.type === 'Bundle'))).map((c) => {
        const n = catalog.filter((g) => g.type === c.key).length;
        const a = el('a', 'kind-other');
        a.href = `../${c.slug}/`;
        a.append(el('span', null, n ? `${n} ${n === 1 ? 'title' : 'titles'}` : 'Coming soon'), el('strong', null, c.name));
        return a;
      }));
    }
    document.title = `${cat.name} by country and state · ${store.name}`;
  }

  async function load() {
    let data = {};
    try { data = await fetch('../guides.json', { cache: 'no-cache' }).then((r) => (r.ok ? r.json() : {})); } catch { data = {}; }
    if (isHttps(data.checkoutEndpoint)) {
      store.endpoint = data.checkoutEndpoint.replace(/\/session\/?$/, '').replace(/\/+$/, '');
      try {
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), 4000);
        const live = await fetch(`${store.endpoint}/catalog`, { signal: controller.signal }).then((r) => (r.ok ? r.json() : null));
        clearTimeout(timer);
        if (live && Array.isArray(live.guides)) data = { ...data, ...live };
      } catch { /* keep guides.json */ }
    }
    if (typeof data.storeName === 'string' && data.storeName.trim()) store.name = data.storeName.trim();
    if (typeof data.currency === 'string' && /^[A-Z]{3}$/.test(data.currency)) store.currency = data.currency;
    store.currencies = Array.isArray(data.currencies) ? data.currencies.filter((c) => /^[A-Z]{3}$/.test(c)) : [];
    try { displayCurrency = localStorage.getItem(CURRENCY_KEY) || ''; } catch { displayCurrency = ''; }
    if (!store.currencies.includes(displayCurrency)) displayCurrency = store.currency;
    setCategories(data.categories);
    const cat = store.categories.find((c) => c.key === KIND) || store.categories[0];
    catalog = (Array.isArray(data.guides) ? data.guides : []).filter((g, i) => {
      if (!g || typeof g !== 'object' || g.status === 'draft') return false;
      if (g.status === 'scheduled' && g.publishAt && Date.parse(g.publishAt) > Date.now()) return false;
      return g.title && g.description && Number.isFinite(Number(g.price)) && (isHttps(g.paymentLink) || /^price_[A-Za-z0-9]+$/.test(String(g.priceId || '')));
    }).map(normalise);
    cart = readStore(CART_KEY);
    renderCartCount();
    // Custom wording from the admin overrides the shell's static copy.
    const h1 = $('#kind-title'); if (h1 && cat.name) { h1.textContent = ''; h1.append(document.createTextNode(`${cat.name}, `), el('em', null, 'filed by place.')); }
    const blurb = $('#kind-blurb'); if (blurb && cat.blurb) blurb.textContent = cat.blurb;
    const format = $('#kind-format'); if (format) format.textContent = cat.format || 'Digital download';
    render(cat, Array.isArray(data.resources) ? data.resources : []);
  }
  load();
})();
